// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { Slider as SliderPrimitive } from "radix-ui";

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  thumbLabels,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root> & {
  thumbLabels?: string[];
}) {
  const _values = React.useMemo(
    () =>
      Array.isArray(value)
        ? value
        : Array.isArray(defaultValue)
          ? defaultValue
          : [min, max],
    [value, defaultValue, min, max],
  );

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn("roc-ui", className)}
      {...props}
    >
      <SliderPrimitive.Track data-slot="slider-track" className={cn("roc-ui")}>
        <SliderPrimitive.Range
          data-slot="slider-range"
          className={cn("roc-ui")}
        />
      </SliderPrimitive.Track>
      {Array.from({ length: _values.length }, (_, index) => (
        <SliderPrimitive.Thumb
          aria-label={
            thumbLabels?.[index] ??
            (_values.length === 1 ? props["aria-label"] : undefined)
          }
          data-slot="slider-thumb"
          key={index}
          className="roc-ui"
        />
      ))}
    </SliderPrimitive.Root>
  );
}

export { Slider };

import "./slider.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="slider"] {
  display: flex;
  align-items: center;
  position: relative;
  width: 100%;
  height: 36px;
  touch-action: none;
  user-select: none;
}
.roc-ui[data-slot="slider-track"] {
  position: relative;
  flex-grow: 1;
  height: 4px;
  border-radius: 99px;
  background: var(--roc-line, #e2e2e2);
  overflow: hidden;
}
.roc-ui[data-slot="slider-range"] {
  position: absolute;
  height: 100%;
  background: var(--roc-ink, #252525);
}
.roc-ui[data-slot="slider-thumb"] {
  display: block;
  position: relative;
  width: 18px;
  height: 18px;
  border: 1px solid var(--roc-line, #bcbcbc);
  border-radius: 50%;
  background: var(--roc-paper, #fff);
  box-shadow: 0 1px 3px #0001;
}
.roc-ui[data-slot="slider-thumb"]::before {
  content: "";
  position: absolute;
  inset: -9px;
}
.roc-ui[data-slot="slider"][data-orientation="vertical"] {
  flex-direction: column;
  width: 36px;
  height: 180px;
}
.roc-ui[data-slot="slider-track"][data-orientation="vertical"] {
  width: 4px;
  height: 100%;
}
.roc-ui[data-slot="slider-range"][data-orientation="vertical"] {
  width: 100%;
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
@keyframes roc-ui-reveal {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
